package com.lordescanor.botforge;import android.os.*;import android.view.*;import android.widget.*;public class SettingsFragment extends androidx.fragment.app.Fragment{public View onCreateView(android.view.LayoutInflater i,ViewGroup p,Bundle b){LinearLayout l=new LinearLayout(getActivity());l.setOrientation(LinearLayout.VERTICAL);l.setPadding(20,20,20,20);l.setBackgroundColor(0xff0B0F14);TextView h=new TextView(getActivity());h.setText("الإعدادات");h.setTextColor(0xffF4F5F7);h.setTextSize(28);h.setPadding(0,0,0,25);l.addView(h);Button clear=new Button(getActivity());clear.setText("مسح قائمة النسخ");clear.setOnClickListener(v->{new BotStore(getActivity()).clear();Toast.makeText(getActivity(),"تم المسح",Toast.LENGTH_SHORT).show();});l.addView(clear);TextView info=new TextView(getActivity());info.setText("BotForge 1.0.0\nالقالب: ORACLE V3\nAndroid minSdk 24");info.setTextColor(0xff9AA5B1);info.setPadding(0,25,0,0);l.addView(info);return l;}}
